use super::*;
use std::collections::VecDeque;
pub(super) struct Max {pub open:bool,pub debug:bool,pub snap_objects:bool,pub db:Option<forge_engine::AssetDatabase>,pub frames:VecDeque<f32>,pub memory:sysinfo::System,pub last:Option<std::time::Instant>,pub bytes:Option<u64>,pub peak_rss:u64,pub cpu_usage:Option<f32>,pub unused_only:bool}
impl Default for Max{fn default()->Self{Self{open:false,debug:false,snap_objects:false,db:None,frames:VecDeque::new(),memory:sysinfo::System::new(),last:None,bytes:None,peak_rss:0,cpu_usage:None,unused_only:false}}}
pub(super) fn brand(ui:&mut egui::Ui){ui.label(format!("Sampled peak RSS: {:.1} MiB · process CPU: {}",e.max.peak_rss as f64/1048576.,e.max.cpu_usage.map(|v|format!("{v:.1}%")).unwrap_or("N/A".into())));let(r,_)=ui.allocate_exact_size(egui::vec2(25.,25.),egui::Sense::hover());let p=ui.painter();let c=egui::Color32::from_rgb(95,166,230);let pt=|x:f32,y:f32|r.min+egui::vec2(x,y);for (a,b) in [(pt(2.,3.),pt(9.,23.)),(pt(9.,3.),pt(23.,8.)),(pt(9.,12.),pt(19.,17.))]{p.rect_filled(egui::Rect::from_two_pos(a,b),1.,c);}}
pub(super) fn menu(ui:&mut egui::Ui,e:&mut Editor){ui.checkbox(&mut e.max.open,tr(e.uk,"База ресурсів / профайлер","Asset database / profiler"));ui.checkbox(&mut e.max.debug,tr(e.uk,"Діагностика","Debug"));ui.checkbox(&mut e.max.snap_objects,tr(e.uk,"Прив’язка до об’єктів","Object snapping"));}
pub(super) fn assets(ui:&mut egui::Ui,e:&mut Editor){if ui.button(tr(e.uk,"Імпорт Aseprite JSON","Import Aseprite JSON")).clicked(){if e.path.is_none(){e.save(false);}if let Some(root)=e.path.as_ref().and_then(|p|p.parent()){if let Some(path)=rfd::FileDialog::new().add_filter("Aseprite JSON Array",&["json"]).pick_file(){match forge_engine::import_aseprite(&path,root){Ok(o)=>{e.selected=Some(o.id);e.project.objects.push(o);e.pro.last_scan=None;e.status="Aseprite imported".into();},Err(err)=>e.status=err}}}}}
pub(super) fn windows(ctx:&egui::Context,e:&mut Editor,diagnostics:Option<&bevy::diagnostic::DiagnosticsStore>){let dt=ctx.input(|i|i.unstable_dt)*1000.;if dt.is_finite()&&dt>0.{e.max.frames.push_back(dt);if e.max.frames.len()>180{e.max.frames.pop_front();}}if e.max.open||e.master.profiler{let now=std::time::Instant::now();if e.max.last.is_none_or(|t|now.duration_since(t).as_secs()>=1){e.max.last=Some(now);if let Ok(pid)=sysinfo::get_current_pid(){e.max.memory.refresh_processes(sysinfo::ProcessesToUpdate::Some(&[pid]),true);e.max.bytes=e.max.memory.process(pid).map(|p|p.memory());e.max.cpu_usage=e.max.memory.process(pid).map(|p|p.cpu_usage());e.max.peak_rss=e.max.peak_rss.max(e.max.bytes.unwrap_or(0));}}let mut open=true;egui::Window::new(tr(e.uk,"Діагностика ресурсів та швидкодії","Assets & performance")).open(&mut open).show(ctx,|ui|{ui.label(format!("Startup to first UI: {:.1} ms",super::FIRST_UI.get().copied().unwrap_or_default()));ui.label(format!("RSS: {}",e.max.bytes.map(|b|format!("{:.1} MiB",b as f64/1048576.)).unwrap_or("N/A".into())));let(r,_)=ui.allocate_exact_size(egui::vec2(ui.available_width().max(160.),100.),egui::Sense::hover());let ceiling=e.max.frames.iter().copied().fold(33.4,f32::max);let pts=e.max.frames.iter().enumerate().map(|(i,&v)|egui::pos2(r.left()+i as f32/179.*r.width(),r.bottom()-v/ceiling*r.height())).collect::<Vec<_>>();if pts.len()>1{ui.painter_at(r).add(egui::Shape::line(pts,egui::Stroke::new(1.5_f32,egui::Color32::LIGHT_GREEN)));}ui.label(format!("Frame {:.1} ms / peak {:.1} ms",dt,ceiling));let (used,hits,misses,evictions)=super::viewport::cache_stats();ui.label(format!("Viewport cache {:.1} MiB | hits {hits} | misses {misses} | evictions {evictions}",used as f64/1048576.));ui.label("Cache estimate, not total GPU memory");let (emitters,slots,bytes)=forge_engine::gpu_particles::stats();let p=e.play.as_ref().unwrap_or(&e.project);ui.separator();ui.label(format!("GPU emitters: {emitters} | allocated slots: {slots} | storage payload: {bytes} B"));ui.label(format!("Scene lights: {} | max per sprite: {}",p.objects.iter().filter(|o|o.pro.light.is_some()).count(),p.settings.gpu_light_count));ui.label(format!("Particle path: {} | generated triangles: {}",if p.settings.gpu_particle_quads{"Vertex quads"}else{"Legacy fullscreen quads"},if p.settings.gpu_particle_quads{slots*2}else{emitters*2}));let mut frames:Vec<_>=e.max.frames.iter().copied().collect();frames.sort_by(f32::total_cmp);if !frames.is_empty(){let n=frames.len()-1;ui.label(format!("Frame median {:.2} ms | P95 {:.2} ms",frames[n/2],frames[n*95/100]));}ui.label("Triangle count is not measured draw calls; frame time is UI/CPU, not GPU timestamp.");let [lr,lh,sr,sh]=forge_engine::gpu_scene::index_cache_stats();ui.label(format!("Light index rebuild/reuse: {lr}/{lh} · blockers: {sr}/{sh}"));let index_ns=forge_engine::gpu_scene::last_index_cpu_ns();ui.label(format!("Last lighting index CPU: {:.3} ms",index_ns as f64/1e6));let sync_ns=forge_engine::gpu_scene::last_sync_cpu_ns();ui.label(format!("Last lighting sync CPU: {:.3} ms (includes index)",sync_ns as f64/1e6));let gpu_pass_ms:std::collections::BTreeMap<String,f64>=diagnostics.into_iter().flat_map(|store|store.iter()).filter(|d|d.path().as_str().starts_with("render/")&&d.path().as_str().ends_with("/elapsed_gpu")).filter_map(|d|d.value().filter(|v|v.is_finite()&&*v>=0.).map(|v|(d.path().as_str().to_owned(),v))).take(128).collect();ui.collapsing("GPU timestamp diagnostics (opt-in)",|ui|{if gpu_pass_ms.is_empty(){ui.small("No GPU samples. Start RUN_EDITOR_GPU_PROFILE.bat on a supported Vulkan/DX12 adapter.");}else{for (path,ms) in &gpu_pass_ms{ui.label(format!("{path}: {ms:.3} ms"));}ui.small("Per-pass latest measurements, potentially delayed; do not sum nested spans.");}});if ui.button("Export performance snapshot (JSON)").clicked(){if let Some(path)=rfd::FileDialog::new().set_file_name("forge-performance.json").save_file(){let snapshot=serde_json::json!({"version":env!("CARGO_PKG_VERSION"),"ui_frame_samples_sorted_ms":frames,"lighting_index_cpu_ns":index_ns,"lighting_sync_cpu_ns":sync_ns,"rss_bytes":e.max.bytes,"sampled_peak_rss_bytes":e.max.peak_rss,"process_cpu_percent":e.max.cpu_usage,"viewport_cache_estimated_bytes":used,"particle_storage_payload_bytes":bytes,"light_index_rebuilds":lr,"light_index_reuses":lh,"blocker_index_rebuilds":sr,"blocker_index_reuses":sh,"gpu_pass_ms":gpu_pass_ms,"gpu_frame_ms":null,"total_vram_bytes":null});e.status=serde_json::to_vec_pretty(&snapshot).map_err(|x|x.to_string()).and_then(|b|std::fs::write(path,b).map_err(|x|x.to_string())).map(|_|"Performance snapshot exported".into()).unwrap_or_else(|x|x);}}if ui.button(tr(e.uk,"Оновити базу","Refresh database")).clicked(){if let Some(root)=e.path.as_ref().and_then(|p|p.parent()){match forge_engine::AssetDatabase::refresh(root,&e.pro.assets,&e.project){Ok(db)=>e.max.db=Some(db),Err(err)=>e.status=err}}}if let Some(db)=&e.max.db{ui.checkbox(&mut e.max.unused_only,"Potentially unused (no scanned direct references)");ui.small("Diagnostic only: dynamic Lua paths, unparsed scenes and external resources may not be detected.");if !db.scan_warnings.is_empty(){ui.colored_label(egui::Color32::LIGHT_RED,format!("{} dependency scan warnings",db.scan_warnings.len()));ui.collapsing("Scan warnings",|ui|{for warning in &db.scan_warnings{ui.small(warning);}});}let unused=db.entries.values().filter(|a|a.present&&a.references.is_empty()).count();ui.label(format!("{unused} potentially unused assets"));ui.collapsing("Transitive dependency graph",|ui|{ui.small(format!("Document cache: {} hits / {} misses",db.cache_hits,db.cache_misses));let id=ui.id().with("dependency32");let mut owner=ui.ctx().data(|d|d.get_temp::<String>(id)).unwrap_or_else(||"Active scene (memory)".into());egui::ComboBox::from_id_salt(id).selected_text(&owner).show_ui(ui,|ui|{for name in db.graph.keys().take(4096){ui.selectable_value(&mut owner,name.clone(),name);}});let(assets,unresolved)=db.transitive_assets(&owner);ui.label(format!("{} reachable resources · {} unresolved links",assets.len(),unresolved.len()));egui::ScrollArea::vertical().max_height(180.).show(ui,|ui|{for p in assets.iter().take(1024){ui.small(p);}for p in unresolved.iter().take(128){ui.colored_label(egui::Color32::LIGHT_RED,p);}});ui.ctx().data_mut(|d|d.insert_temp(id,owner));});ui.collapsing("Reverse dependency graph",|ui|{let mut by_owner=std::collections::BTreeMap::<&str,Vec<&str>>::new();for (path,a) in &db.entries{for owner in &a.references{by_owner.entry(owner.as_str()).or_default().push(path.as_str());}}for (owner,paths) in by_owner.iter().take(512){ui.collapsing(*owner,|ui|{for path in paths.iter().take(128){ui.small(*path);}});}});egui::ScrollArea::vertical().max_height(220.).show(ui,|ui|{for (path,a) in &db.entries{if e.max.unused_only&&(!a.present||!a.references.is_empty()){continue;}ui.collapsing(format!("{} · {} refs",path,a.references.len()),|ui|{ui.monospace(a.id.to_string());ui.label(format!("{} bytes · present {}",a.bytes,a.present));for x in &a.references{ui.label(x);}});}});}});if !open{e.max.open=false;e.master.profiler=false;}}
 if e.max.debug{let mut open=true;egui::Window::new(tr(e.uk,"Діагностика гри","Game debug")).open(&mut open).show(ctx,|ui|{let p=e.play.as_ref().unwrap_or(&e.project);ui.label(format!("Simulation: {:.3}s",e.sim.elapsed));ui.checkbox(&mut e.tools.colliders,tr(e.uk,"Колізії","Colliders"));if let Some(o)=p.objects.iter().find(|o|Some(o.id)==e.selected){ui.monospace(format!("{}\nID {}\nX {:.2} Y {:.2}\nAngle {:.2}\nBody {:?}\nClip {}",o.name,o.id,o.position[0],o.position[1],o.rotation,o.body,o.clip_name));}ui.separator();egui::ScrollArea::vertical().max_height(200.).show(ui,|ui|{for event in e.sim.events.iter().rev().take(20){ui.label(event);}for err in e.sim.errors.iter().rev(){ui.colored_label(egui::Color32::LIGHT_RED,err);}});});e.max.debug=open;}}
pub(super) fn snap(e:&mut Editor){if !e.max.snap_objects||e.gizmo!=0||e.drag_start.is_none(){return;}let candidates=e.project.objects.iter().filter(|o|Some(o.id)!=e.selected&&!e.pro.multi.contains(&o.id)).map(|o|o.position).collect::<Vec<_>>();let tolerance=8./e.zoom.max(0.2);for o in e.project.objects.iter_mut().filter(|o|Some(o.id)==e.selected||e.pro.multi.contains(&o.id)){for axis in 0..2{if e.tools.axis!=0&&e.tools.axis!=axis+1{continue;}if let Some(v)=candidates.iter().map(|p|p[axis]).filter(|v|(*v-o.position[axis]).abs()<=tolerance).min_by(|a,b|(*a-o.position[axis]).abs().total_cmp(&(*b-o.position[axis]).abs())){o.position[axis]=v;}}}}

pub(super) fn dock_tabs(ui:&mut egui::Ui,e:&mut Editor){ui.horizontal_wrapped(|ui|{for (i,label) in [tr(e.uk,"Сцена","Scene"),tr(e.uk,"Інспектор","Inspector"),tr(e.uk,"Інструменти","Tools")].iter().enumerate(){let r=ui.add(egui::Label::new(*label).sense(egui::Sense::click_and_drag()));r.dnd_set_drag_payload(i);r.context_menu(|ui|{for (zone,name) in ["Left","Right","Bottom","Top","Float"].iter().enumerate(){if ui.button(*name).clicked(){if zone<4{e.master.settings.dock[i]=zone;}match i{0=>e.workspace.prefs.scene=zone==4,1=>e.workspace.prefs.inspector=zone==4,_=>e.workspace.prefs.bottom=zone==4};ui.close_menu();}}});}if ui.small_button("Save dock").clicked(){super::master::save(e);super::workspace::save(e);}ui.separator();for (zone,label) in [tr(e.uk,"Ліворуч","Left"),tr(e.uk,"Праворуч","Right"),tr(e.uk,"Знизу","Bottom"),tr(e.uk,"Зверху","Top")].iter().enumerate(){let r=ui.button(*label);if let Some(i)=r.dnd_release_payload::<usize>(){if *i<3{e.master.settings.dock[*i]=zone;match *i{0=>e.workspace.prefs.scene=false,1=>e.workspace.prefs.inspector=false,_=>e.workspace.prefs.bottom=false};}}}let r=ui.button(tr(e.uk,"Плаваюча","Float"));if let Some(i)=r.dnd_release_payload::<usize>(){match *i{0=>e.workspace.prefs.scene=true,1=>e.workspace.prefs.inspector=true,2=>e.workspace.prefs.bottom=true,_=>{}}}});}
